import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_01_agent_loop.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_02_four_entries.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_03_sandbox_approval.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_06_three_layers.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_04_cost_context.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_05_provider_protocol.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_07_learning_path.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_08_foundation_stack.png",A=JSON.parse('{"title":"别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑","description":"真正改变软件开发的，不是 AI 能不能写出一段漂亮代码，而是它能不能进入真实工程环境：读懂仓库、调用工具、修改文件、运行验证，再把证据交回给人。Codex 的价值就在这条执行闭环里。理解这套底层逻辑之后，桌面 App、CLI、IDE、云端任务、模型和计费就不再是一堆零散功能，而是同一个代理系统的不同","frontmatter":{"title":"别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑","description":"真正改变软件开发的，不是 AI 能不能写出一段漂亮代码，而是它能不能进入真实工程环境：读懂仓库、调用工具、修改文件、运行验证，再把证据交回给人。Codex 的价值就在这条执行闭环里。理解这套底层逻辑之后，桌面 App、CLI、IDE、云端任务、模型和计费就不再是一堆零散功能，而是同一个代理系统的不同","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 智能代理七章","readingTime":11,"source":"2026-08-10/ai_codex_01_agent_foundation.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_01_01_agent_loop.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-01-agent-foundation"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑"}],["meta",{"property":"og:description","content":"真正改变软件开发的，不是 AI 能不能写出一段漂亮代码，而是它能不能进入真实工程环境：读懂仓库、调用工具、修改文件、运行验证，再把证据交回给人。Codex 的价值就在这条执行闭环里。理解这套底层逻辑之后，桌面 App、CLI、IDE、云端任务、模型和计费就不再是一堆零散功能，而是同一个代理系统的不同"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-01-agent-foundation"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_01_agent_loop.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑"}],["meta",{"name":"twitter:description","content":"真正改变软件开发的，不是 AI 能不能写出一段漂亮代码，而是它能不能进入真实工程环境：读懂仓库、调用工具、修改文件、运行验证，再把证据交回给人。Codex 的价值就在这条执行闭环里。理解这套底层逻辑之后，桌面 App、CLI、IDE、云端任务、模型和计费就不再是一堆零散功能，而是同一个代理系统的不同"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_01_01_agent_loop.png"}]],"prev":false,"next":{"text":"四种入口，一套大脑：从第一个任务到 AGENTS.md 的 Codex 上手地图","link":"/ai/ai-codex-02-four-entries-and-agents"}},"headers":[],"relativePath":"ai/ai-codex-01-agent-foundation.md","filePath":"ai/ai-codex-01-agent-foundation.md","lastUpdated":null}'),_={name:"ai/ai-codex-01-agent-foundation.md"};function u(m,a,x,b,g,f){return t(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="别再把-codex-当聊天框-一文看懂-ai-编程代理的底层逻辑" tabindex="-1">别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑 <a class="header-anchor" href="#别再把-codex-当聊天框-一文看懂-ai-编程代理的底层逻辑" aria-label="Permalink to &quot;别再把 Codex 当聊天框：一文看懂 AI 编程代理的底层逻辑&quot;">​</a></h1><p>真正改变软件开发的，不是 AI 能不能写出一段漂亮代码，而是它能不能进入真实工程环境：读懂仓库、调用工具、修改文件、运行验证，再把证据交回给人。Codex 的价值就在这条执行闭环里。理解这套底层逻辑之后，桌面 App、CLI、IDE、云端任务、模型和计费就不再是一堆零散功能，而是同一个代理系统的不同入口与资源配置。</p><p>本文归纳「AI 编程指南」Codex 系列基础入门章的 5 篇文章，并用 OpenAI Docs 重新核对产品边界。重点不是记住某个版本的按钮与价格，而是建立一套经得起版本变化的心智模型：代理如何行动，权限如何约束，成本为什么产生，第三方模型为什么并非换个地址那么简单。</p><h2 id="一、从生成代码到完成任务" tabindex="-1">一、从生成代码到完成任务 <a class="header-anchor" href="#一、从生成代码到完成任务" aria-label="Permalink to &quot;一、从生成代码到完成任务&quot;">​</a></h2><h3 id="_1-1-聊天模型交付答案-编程代理交付状态变化" tabindex="-1">1.1 聊天模型交付答案，编程代理交付状态变化 <a class="header-anchor" href="#_1-1-聊天模型交付答案-编程代理交付状态变化" aria-label="Permalink to &quot;1.1 聊天模型交付答案，编程代理交付状态变化&quot;">​</a></h3><p>传统聊天式编程的基本单位是一轮回答。你描述问题，模型给出代码片段或建议，复制、落盘、运行、排错和回滚仍由你完成。编程代理的基本单位则是一项任务：它需要观察环境、形成行动、读取结果，并根据结果决定下一步。</p><p>这意味着评价标准也发生了变化。回答是否流畅已经不够，真正重要的是：它读了哪些文件，为什么修改这些位置，执行了哪些命令，测试是否通过，还有哪些风险没有被验证。</p><p>一个最小代理闭环可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>读取项目与规则</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>制定局部行动</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>调用文件、Shell、搜索或测试工具</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>观察真实结果</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>继续、修正、暂停审批或交付证据</span></span></code></pre></div><p>这里的关键不是“自主”两个字，而是反馈。没有真实工具结果，模型只是在推测；有了结果但不根据结果修正，也只是自动执行脚本。代理之所以像一位工程协作者，是因为推理与环境反馈被串成了循环。</p><p><img src="`+r+'" alt="图 1：从聊天回答到代理执行闭环"></p><h3 id="_1-2-人的角色没有消失-而是上移了" tabindex="-1">1.2 人的角色没有消失，而是上移了 <a class="header-anchor" href="#_1-2-人的角色没有消失-而是上移了" aria-label="Permalink to &quot;1.2 人的角色没有消失，而是上移了&quot;">​</a></h3><p>代理能执行，不代表它应当替人拍板。需求取舍、架构方向、风险承受、生产变更和最终验收仍然属于人。AI 更适合承担高频观察、候选方案、局部修改、机械验证和证据整理。</p><p>更准确的协作关系是：人定义目标和不可越过的边界，代理在边界内探索与执行，人再依据 diff、日志、测试和业务结果决定是否接受。把它当成“自动正确的程序”会失控，把它只当成“更会聊天的搜索框”又浪费了执行能力。</p><h3 id="_1-3-一次可靠交付至少包含四类证据" tabindex="-1">1.3 一次可靠交付至少包含四类证据 <a class="header-anchor" href="#_1-3-一次可靠交付至少包含四类证据" aria-label="Permalink to &quot;1.3 一次可靠交付至少包含四类证据&quot;">​</a></h3><ul><li>范围证据：实际读取和修改了哪些文件。</li><li>行为证据：执行了哪些命令，工具返回了什么。</li><li>验证证据：测试、构建、静态检查或运行观测是否达到要求。</li><li>边界证据：哪些结论尚未验证，哪些操作因为权限或风险没有执行。</li></ul><p>这四类证据把“它说完成了”改造成“你能复核它是否完成”。这是 AI 编程从演示走向工程的分水岭。</p><h2 id="二、四种入口只是四种工作台" tabindex="-1">二、四种入口只是四种工作台 <a class="header-anchor" href="#二、四种入口只是四种工作台" aria-label="Permalink to &quot;二、四种入口只是四种工作台&quot;">​</a></h2><h3 id="_2-1-本机入口共享同一套项目现实" tabindex="-1">2.1 本机入口共享同一套项目现实 <a class="header-anchor" href="#_2-1-本机入口共享同一套项目现实" aria-label="Permalink to &quot;2.1 本机入口共享同一套项目现实&quot;">​</a></h3><p>桌面 App、CLI 和 IDE 扩展都可以在本机项目上工作。它们面对的是同一类真实对象：本地文件、Git 工作树、编译器、测试环境和系统权限。差别主要在交互方式。</p><p>桌面 App 强在任务编排、可视化 diff 和多线程管理；CLI 强在可组合命令、远程环境和自动化；IDE 扩展强在利用当前文件、选区和编辑器上下文减少描述成本。没有哪个入口天然“更聪明”，真正决定结果的是模型、上下文、工具、权限和验收标准。</p><h3 id="_2-2-云端入口改变的是执行地点" tabindex="-1">2.2 云端入口改变的是执行地点 <a class="header-anchor" href="#_2-2-云端入口改变的是执行地点" aria-label="Permalink to &quot;2.2 云端入口改变的是执行地点&quot;">​</a></h3><p>云端任务把仓库和任务放进托管隔离环境。它适合耗时较长、可以通过 Git 仓库重建环境、能够用测试或 diff 验收的工作。它不直接拥有本机未提交文件、私有设备状态或随手配置，因此环境初始化、Secrets、网络白名单和依赖缓存变成了核心问题。</p><p>本地与云端不是高低关系，而是两个执行域。贴近本机硬件、依赖当前进程或需要频繁人工观察的任务更适合本地；可以明确输入、并行运行、独立验收的任务更适合云端。</p><p><img src="'+n+'" alt="图 2：桌面、CLI、IDE 与云端入口的执行域"></p><h3 id="_2-3-入口选择应由任务摩擦决定" tabindex="-1">2.3 入口选择应由任务摩擦决定 <a class="header-anchor" href="#_2-3-入口选择应由任务摩擦决定" aria-label="Permalink to &quot;2.3 入口选择应由任务摩擦决定&quot;">​</a></h3><p>如果任务需要反复点选界面、逐块审查改动，桌面端降低摩擦；如果需要 SSH、管道、脚本和 CI，CLI 更自然；如果问题集中在当前代码选区，IDE 最省上下文；如果任务会运行很久且能独立交付，云端更合适。</p><p>不要把学习入口误解为学习四套产品。先学会目标、上下文、权限、验证这条主线，再迁移到其他入口，成本远低于记忆每个平台的按钮。</p><h2 id="三、沙箱与审批构成双重控制" tabindex="-1">三、沙箱与审批构成双重控制 <a class="header-anchor" href="#三、沙箱与审批构成双重控制" aria-label="Permalink to &quot;三、沙箱与审批构成双重控制&quot;">​</a></h2><h3 id="_3-1-沙箱回答-技术上能碰什么" tabindex="-1">3.1 沙箱回答“技术上能碰什么” <a class="header-anchor" href="#_3-1-沙箱回答-技术上能碰什么" aria-label="Permalink to &quot;3.1 沙箱回答“技术上能碰什么”&quot;">​</a></h3><p>沙箱限制代理能够读取或写入的文件范围、能否访问网络以及哪些系统能力可用。它是一道技术边界，不会因为提示词写得强硬就自动消失。</p><p>只读任务应尽量停留在读取范围；需要修改项目时开放工作区写入；只有在独立、可丢弃、没有敏感数据的隔离环境中，才有理由考虑更宽权限。权限不是能力勋章，越宽只代表潜在影响面越大。</p><h3 id="_3-2-审批回答-跨界前是否必须问人" tabindex="-1">3.2 审批回答“跨界前是否必须问人” <a class="header-anchor" href="#_3-2-审批回答-跨界前是否必须问人" aria-label="Permalink to &quot;3.2 审批回答“跨界前是否必须问人”&quot;">​</a></h3><p>审批策略与沙箱是两个独立旋钮。一个命令即使理论上能执行，也可以要求先停下来说明目的、目标和风险；一个命令即使无需询问，仍然可能被沙箱技术性阻止。</p><p>理解这一区别，很多“Codex 为什么不听话”的问题就消失了。它可能不是不会做，而是当前文件不在可写范围；也可能不是被技术拦住，而是进入了需要人工决定的风险节点。</p><h3 id="_3-3-安全的默认策略是逐步放宽" tabindex="-1">3.3 安全的默认策略是逐步放宽 <a class="header-anchor" href="#_3-3-安全的默认策略是逐步放宽" aria-label="Permalink to &quot;3.3 安全的默认策略是逐步放宽&quot;">​</a></h3><p>从最小权限开始，根据任务证据逐步放宽，比一开始完全开放更稳。需要网络时只开放必要域名，需要写入时只开放目标目录，需要安装或发布时明确停下来确认。权限应该和任务生命周期一起变化，而不是成为永久全开配置。</p><p><img src="'+s+'" alt="图 3：沙箱技术边界与审批决策边界"></p><h2 id="四、agents-md-与记忆不是一回事" tabindex="-1">四、AGENTS.md 与记忆不是一回事 <a class="header-anchor" href="#四、agents-md-与记忆不是一回事" aria-label="Permalink to &quot;四、AGENTS.md 与记忆不是一回事&quot;">​</a></h2><h3 id="_4-1-项目规范应由人显式维护" tabindex="-1">4.1 项目规范应由人显式维护 <a class="header-anchor" href="#_4-1-项目规范应由人显式维护" aria-label="Permalink to &quot;4.1 项目规范应由人显式维护&quot;">​</a></h3><p><code>AGENTS.md</code> 适合记录稳定、可审查、应当强制遵守的项目事实，例如目录职责、测试命令、编码约定、禁止操作、提交范围和交付条件。它是项目治理文件，不是聊天摘要。</p><p>真正有价值的规则通常具备三个特征：能够影响行动、能够被验证、在多次任务中持续成立。把整份架构史、长篇教程或临时讨论塞进去，只会稀释关键约束。</p><h3 id="_4-2-自动记忆适合保存低风险偏好" tabindex="-1">4.2 自动记忆适合保存低风险偏好 <a class="header-anchor" href="#_4-2-自动记忆适合保存低风险偏好" aria-label="Permalink to &quot;4.2 自动记忆适合保存低风险偏好&quot;">​</a></h3><p>Memories 一类自动记忆更适合保存稳定偏好、常用工作流和已验证经验，但不适合承载密钥、临时账号、未经确认的结论或必须强制执行的安全红线。自动记忆是辅助上下文，不应成为唯一事实源。</p><p>稳定项目规则进入版本控制，个人长期偏好进入用户级配置或记忆，当前任务细节留在会话和计划中。分清三层，才能避免旧结论在新任务里悄悄污染判断。</p><p><img src="'+l+'" alt="图 4：上下文、项目规则与记忆的三层边界"></p><h2 id="五、成本来自上下文与推理-不来自按钮数量" tabindex="-1">五、成本来自上下文与推理，不来自按钮数量 <a class="header-anchor" href="#五、成本来自上下文与推理-不来自按钮数量" aria-label="Permalink to &quot;五、成本来自上下文与推理，不来自按钮数量&quot;">​</a></h2><h3 id="_5-1-订阅和-api-是两种资源结算方式" tabindex="-1">5.1 订阅和 API 是两种资源结算方式 <a class="header-anchor" href="#_5-1-订阅和-api-是两种资源结算方式" aria-label="Permalink to &quot;5.1 订阅和 API 是两种资源结算方式&quot;">​</a></h3><p>ChatGPT 订阅提供的是套餐内使用能力，API 则按照实际调用量结算。具体套餐、额度、模型和价格变化很快，不应该写死在学习笔记里。真正稳定的认知是：每次任务都要把相关上下文交给模型处理，读取越多、推理越深、往返越多，消耗通常越大。</p><p>因此“问了几句话”不是可靠成本指标。一条需要扫描大型仓库、读取长日志并反复验证的指令，可能比多轮简单问答更昂贵。</p><h3 id="_5-2-省成本的本质是减少无效计算" tabindex="-1">5.2 省成本的本质是减少无效计算 <a class="header-anchor" href="#_5-2-省成本的本质是减少无效计算" aria-label="Permalink to &quot;5.2 省成本的本质是减少无效计算&quot;">​</a></h3><ul><li>给出准确范围，避免全仓库盲搜。</li><li>把验收标准写清，减少来回返工。</li><li>将稳定规则放进项目文件，避免每次重复解释。</li><li>简单任务使用合适的模型与推理强度。</li><li>先读错误摘要，再按证据展开相关文件。</li></ul><p>这些做法同时提高速度、准确率和成本效率。真正昂贵的往往不是一次深思，而是信息不足导致的多轮走偏。</p><p><img src="'+p+'" alt="图 5：任务上下文、推理与返工共同构成成本"></p><h2 id="六、第三方模型不是-换个网址" tabindex="-1">六、第三方模型不是“换个网址” <a class="header-anchor" href="#六、第三方模型不是-换个网址" aria-label="Permalink to &quot;六、第三方模型不是“换个网址”&quot;">​</a></h2><h3 id="_6-1-模型提供商包含协议契约" tabindex="-1">6.1 模型提供商包含协议契约 <a class="header-anchor" href="#_6-1-模型提供商包含协议契约" aria-label="Permalink to &quot;6.1 模型提供商包含协议契约&quot;">​</a></h3><p>Codex 与模型服务之间不仅传递一段文本，还可能包含工具定义、结构化输出、推理事件、流式增量和错误语义。第三方服务即使宣称兼容某种 OpenAI 接口，也不代表完整支持代理所需的协议行为。</p><p>所以第三方接入要检查的不只是 <code>base_url</code> 和模型名，还包括认证方式、请求协议、工具调用、响应事件、上下文限制以及失败重试。配置能被读取，只说明语法正确；真实工具调用完成，才说明链路可用。</p><h3 id="_6-2-密钥只应通过受控环境传入" tabindex="-1">6.2 密钥只应通过受控环境传入 <a class="header-anchor" href="#_6-2-密钥只应通过受控环境传入" aria-label="Permalink to &quot;6.2 密钥只应通过受控环境传入&quot;">​</a></h3><p>API Key 不应写进文章、仓库、日志或可提交配置。配置文件只引用环境变量名，密钥由本机安全存储、CI Secrets 或受控运行环境注入。代理能读取某个环境变量，不代表它应该被暴露给所有工具和所有子进程。</p><h3 id="_6-3-第三方接入必须单独验收" tabindex="-1">6.3 第三方接入必须单独验收 <a class="header-anchor" href="#_6-3-第三方接入必须单独验收" aria-label="Permalink to &quot;6.3 第三方接入必须单独验收&quot;">​</a></h3><p>一个合理的验收路径应覆盖模型识别、最小对话、工具调用、文件修改、结构化输出、错误恢复和计费观测。只测试“你好，能回复吗”无法证明它能承担编程代理任务。</p><p><img src="'+d+'" alt="图 6：第三方模型接入需要跨过协议与安全边界"></p><h2 id="七、建立自己的最小学习闭环" tabindex="-1">七、建立自己的最小学习闭环 <a class="header-anchor" href="#七、建立自己的最小学习闭环" aria-label="Permalink to &quot;七、建立自己的最小学习闭环&quot;">​</a></h2><h3 id="_7-1-用玩具仓库观察而不是猜" tabindex="-1">7.1 用玩具仓库观察而不是猜 <a class="header-anchor" href="#_7-1-用玩具仓库观察而不是猜" aria-label="Permalink to &quot;7.1 用玩具仓库观察而不是猜&quot;">​</a></h3><p>创建一个可以随时丢弃的小仓库，准备一段简单代码和一条测试。让 Codex 先解释文件，再做一个局部修改，随后检查 diff、运行测试并记录它在哪些操作上请求了审批。这个练习比背命令更重要，因为它把代理、工具、沙箱、审批和验证同时变成了可观察行为。</p><h3 id="_7-2-把-完成-改写成可验证目标" tabindex="-1">7.2 把“完成”改写成可验证目标 <a class="header-anchor" href="#_7-2-把-完成-改写成可验证目标" aria-label="Permalink to &quot;7.2 把“完成”改写成可验证目标&quot;">​</a></h3><p>不要只说“帮我优化一下”。说明目标文件、不能改变的行为、允许修改的范围、必须执行的检查，以及无法验证时应如何报告。你给出的完成定义越清晰，代理越不需要替你做产品决策。</p><h3 id="_7-3-形成长期可复用的三层知识" tabindex="-1">7.3 形成长期可复用的三层知识 <a class="header-anchor" href="#_7-3-形成长期可复用的三层知识" aria-label="Permalink to &quot;7.3 形成长期可复用的三层知识&quot;">​</a></h3><ul><li>官方文档保存当前产品事实。</li><li><code>AGENTS.md</code> 保存项目必须遵守的稳定规则。</li><li>个人笔记保存实践判断、失败案例和适用条件。</li></ul><p>三层分开后，工具升级不会摧毁你的知识体系。按钮、模型和价格会变，但目标、上下文、权限、反馈、验证和责任边界仍然成立。</p><p><img src="'+c+'" alt="图 7：从最小任务到工程自动化的学习路径"></p><p><img src="'+h+'" alt="图 8：模型、上下文、工具、权限与验证组成代理栈"></p><h2 id="八、结语" tabindex="-1">八、结语 <a class="header-anchor" href="#八、结语" aria-label="Permalink to &quot;八、结语&quot;">​</a></h2><p>Codex 的底层价值不是“更会写代码”，而是把语言模型放进一个受约束、可观察、能验证的工程循环。入口决定你从哪里下达任务，模型决定推理能力，工具决定能做什么，沙箱和审批决定能做到哪里，<code>AGENTS.md</code> 决定如何遵守项目规则，测试和 diff 决定你是否应该接受结果。</p><p>真正值得学习的不是某个版本的菜单，而是这套控制系统。掌握它之后，你面对任何新的编程代理，都能迅速判断：它如何获取上下文，如何行动，如何被约束，如何证明自己做对了。</p><h2 id="九、参考资料" tabindex="-1">九、参考资料 <a class="header-anchor" href="#九、参考资料" aria-label="Permalink to &quot;九、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/01-what-is-codex" target="_blank" rel="noreferrer">AI 编程指南：认识 Codex 与四种入口</a></p><p><a href="https://coding.stormzhang.ai/codex/02-core-concepts" target="_blank" rel="noreferrer">AI 编程指南：Codex 核心概念速览</a></p><p><a href="https://coding.stormzhang.ai/codex/03-install" target="_blank" rel="noreferrer">AI 编程指南：安装与登录</a></p><p><a href="https://coding.stormzhang.ai/codex/04-pricing" target="_blank" rel="noreferrer">AI 编程指南：订阅与计费</a></p><p><a href="https://coding.stormzhang.ai/codex/05-third-party-models" target="_blank" rel="noreferrer">AI 编程指南：接入第三方模型</a></p><p><a href="https://developers.openai.com/codex/" target="_blank" rel="noreferrer">OpenAI Docs：Codex</a></p><p><a href="https://developers.openai.com/codex/config-basic" target="_blank" rel="noreferrer">OpenAI Docs：Codex 配置</a></p><p><a href="https://github.com/stormzhang/ai-coding-guide" target="_blank" rel="noreferrer">原教程仓库与 MIT License</a></p>',85)])])}const I=e(_,[["render",u]]);export{A as __pageData,I as default};
